//! CABIN · YARD
//!   · the track graph of one station: nodes, edges, points, crossings,
//!     platforms, portals and signals
//!   · Graph: which edge a train may take next, obeying points and crossings
//!   · written only by `cabin-osm`, read by the game; a plain text file so a
//!     diff shows exactly which track or signal moved
//!
//! Track comes from OpenStreetMap. Signals are generated by rule
//! (`signal.rs`) and moved or renamed by the overrides file; OpenStreetMap
//! holds 2 for the whole station, so none come from it. Routes are not
//! stored: `route.rs` builds them at load. Positions are metres east and
//! north of `origin`, so the sim never sees a latitude.
//!
//! Format, one record per line, numbers with one decimal so the same extract
//! always writes the same bytes:
//!   yard 3
//!   origin <lat> <lon>
//!   base <OSM timestamp>
//!   promoted <way id> <kind it was tagged>      a yard or siding way read as running
//!   node <osm id> <x> <y>
//!   edge <a> <b> <kind> <length> <way id> <x,y;x,y;...>
//!   point <node> <stem> <normal> <reverse>
//!   crossing <node> <e1> <e2> <e3> <e4> [...]  pairs (e1,e2), (e3,e4), ...: two
//!                     for a diamond, more for a slip (version 3; version 2 had
//!                     exactly two)
//!   platform <name, no spaces> <edge> <length> <way id>
//!   portal <name> <node> <edge>
//!   signal <name> <kind> <edge> <offset> <ab|ba> <origin> <platform|->
//!                     offset in metres from the edge's `a` end; `ab` faces
//!                     trains running from `a` to `b`

use std::fmt::Write;

pub const FORMAT_VERSION: u32 = 3;

/// What a track is for. Only `Running` is worked by the player; `Yard` and
/// `Siding` are drawn and never routed (plan, "What is worked").
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Kind {
    Running,
    Yard,
    Siding,
}

impl Kind {
    pub fn name(self) -> &'static str {
        match self {
            Kind::Running => "running",
            Kind::Yard => "yard",
            Kind::Siding => "siding",
        }
    }
    pub fn from_name(s: &str) -> Option<Kind> {
        match s {
            "running" => Some(Kind::Running),
            "yard" => Some(Kind::Yard),
            "siding" => Some(Kind::Siding),
            _ => None,
        }
    }
}

#[derive(Clone, Debug, PartialEq)]
pub struct Node {
    pub osm: u64,
    pub x: f64,
    pub y: f64,
}

/// One track section between two junctions, with its drawn shape.
#[derive(Clone, Debug, PartialEq)]
pub struct Edge {
    pub a: usize,
    pub b: usize,
    pub kind: Kind,
    pub len: f64,
    pub way: u64,
    pub poly: Vec<(f64, f64)>,
}

/// A turnout: trains arriving on the stem choose a leg; trains arriving on a
/// leg can only take the stem. `normal` is the leg closer to straight.
#[derive(Clone, Debug, PartialEq)]
pub struct Point {
    pub node: usize,
    pub stem: usize,
    pub normal: usize,
    pub reverse: usize,
}

/// Two tracks crossing at one node. Each pair is a way through it. A diamond
/// has the two straight pairs only: no way to change from one track to the
/// other. A slip also lists the diverging pairs, straight pairs first, so
/// "the first way on" is the straight one. A slip has moving parts, but a
/// route over it holds the whole crossing, so the route's own path is its
/// setting while the route stands.
#[derive(Clone, Debug, PartialEq)]
pub struct Crossing {
    pub node: usize,
    pub pairs: Vec<(usize, usize)>,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Platform {
    pub name: String,
    pub way: u64,
    pub edge: usize,
    pub len: f64,
}

/// Where a running line leaves the extract; trains are offered here.
#[derive(Clone, Debug, PartialEq)]
pub struct Portal {
    pub name: String,
    pub node: usize,
    pub edge: usize,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum SignalKind {
    /// Stands outside all connections on an approach line (C3-58 "outside all connections").
    Home,
    /// Stands at a platform end, protecting the first facing points (C3-63 "the first facing points").
    Starter,
}

impl SignalKind {
    pub fn name(self) -> &'static str {
        match self {
            SignalKind::Home => "home",
            SignalKind::Starter => "starter",
        }
    }
    pub fn from_name(s: &str) -> Option<SignalKind> {
        match s {
            "home" => Some(SignalKind::Home),
            "starter" => Some(SignalKind::Starter),
            _ => None,
        }
    }
}

/// Where a signal's position came from; the "what is real" panel tags both
/// `authored`. No signal comes from OpenStreetMap.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Origin {
    Generated,
    Override,
}

impl Origin {
    pub fn name(self) -> &'static str {
        match self {
            Origin::Generated => "generated",
            Origin::Override => "override",
        }
    }
    pub fn from_name(s: &str) -> Option<Origin> {
        match s {
            "generated" => Some(Origin::Generated),
            "override" => Some(Origin::Override),
            _ => None,
        }
    }
}

/// A stop signal. It governs trains running over `edge` in one direction:
/// `forward` means from the edge's `a` end towards `b`.
#[derive(Clone, Debug, PartialEq)]
pub struct Signal {
    pub name: String,
    pub kind: SignalKind,
    pub edge: usize,
    /// Metres from the edge's `a` end.
    pub offset: f64,
    pub forward: bool,
    pub origin: Origin,
    /// A Starter's platform: a train stopped at this signal is berthed there.
    pub platform: Option<usize>,
}

#[derive(Clone, Debug, PartialEq, Default)]
pub struct Yard {
    pub origin: (f64, f64),
    pub osm_base: String,
    /// Ways OpenStreetMap tags yard or siding that the extractor reads as
    /// running because a platform needs them. Assumed, not mapped: the panel
    /// tags them. Each entry is (way id, the kind OpenStreetMap gave it).
    pub promoted: Vec<(u64, Kind)>,
    pub nodes: Vec<Node>,
    pub edges: Vec<Edge>,
    pub points: Vec<Point>,
    pub crossings: Vec<Crossing>,
    pub platforms: Vec<Platform>,
    pub portals: Vec<Portal>,
    pub signals: Vec<Signal>,
}

#[derive(Debug, PartialEq)]
pub struct YardError(pub String);

impl Yard {
    /// Round every number to the precision the file keeps, so a yard built in
    /// memory equals the same yard read back from its file.
    pub fn quantised(mut self) -> Yard {
        let r1 = |v: f64| (v * 10.0).round() / 10.0;
        let r6 = |v: f64| (v * 1e6).round() / 1e6;
        self.origin = (r6(self.origin.0), r6(self.origin.1));
        for n in &mut self.nodes {
            n.x = r1(n.x);
            n.y = r1(n.y);
        }
        for e in &mut self.edges {
            e.len = r1(e.len);
            for p in &mut e.poly {
                *p = (r1(p.0), r1(p.1));
            }
        }
        for p in &mut self.platforms {
            p.len = r1(p.len);
        }
        for s in &mut self.signals {
            s.offset = r1(s.offset);
        }
        self
    }

    pub fn to_text(&self) -> String {
        let mut s = String::new();
        let _ = writeln!(s, "yard {FORMAT_VERSION}");
        let _ = writeln!(s, "origin {:.6} {:.6}", self.origin.0, self.origin.1);
        let _ = writeln!(s, "base {}", self.osm_base);
        for (way, was) in &self.promoted {
            let _ = writeln!(s, "promoted {way} {}", was.name());
        }
        for n in &self.nodes {
            let _ = writeln!(s, "node {} {:.1} {:.1}", n.osm, n.x, n.y);
        }
        for e in &self.edges {
            let poly: Vec<String> = e.poly.iter().map(|p| format!("{:.1},{:.1}", p.0, p.1)).collect();
            let _ = writeln!(
                s,
                "edge {} {} {} {:.1} {} {}",
                e.a, e.b, e.kind.name(), e.len, e.way, poly.join(";")
            );
        }
        for p in &self.points {
            let _ = writeln!(s, "point {} {} {} {}", p.node, p.stem, p.normal, p.reverse);
        }
        for c in &self.crossings {
            let pairs: Vec<String> = c.pairs.iter().map(|p| format!("{} {}", p.0, p.1)).collect();
            let _ = writeln!(s, "crossing {} {}", c.node, pairs.join(" "));
        }
        for p in &self.platforms {
            let _ = writeln!(s, "platform {} {} {:.1} {}", p.name, p.edge, p.len, p.way);
        }
        for p in &self.portals {
            let _ = writeln!(s, "portal {} {} {}", p.name, p.node, p.edge);
        }
        for g in &self.signals {
            let _ = writeln!(
                s,
                "signal {} {} {} {:.1} {} {} {}",
                g.name,
                g.kind.name(),
                g.edge,
                g.offset,
                if g.forward { "ab" } else { "ba" },
                g.origin.name(),
                g.platform.map_or("-".to_string(), |p| p.to_string())
            );
        }
        s
    }

    pub fn parse(text: &str) -> Result<Yard, YardError> {
        let mut y = Yard::default();
        let mut seen_header = false;
        for (k, line) in text.lines().enumerate() {
            let bad = |what: &str| YardError(format!("line {}: {what}: {line}", k + 1));
            let f: Vec<&str> = line.split_whitespace().collect();
            if f.is_empty() {
                continue;
            }
            let num = |i: usize| -> Result<f64, YardError> {
                f.get(i).and_then(|v| v.parse().ok()).ok_or_else(|| bad("bad number"))
            };
            let idx = |i: usize| -> Result<usize, YardError> {
                f.get(i).and_then(|v| v.parse().ok()).ok_or_else(|| bad("bad index"))
            };
            let id = |i: usize| -> Result<u64, YardError> {
                f.get(i).and_then(|v| v.parse().ok()).ok_or_else(|| bad("bad id"))
            };
            match f[0] {
                "yard" => {
                    if f.get(1) != Some(&"3") {
                        return Err(bad("unsupported yard format version"));
                    }
                    seen_header = true;
                }
                "origin" => y.origin = (num(1)?, num(2)?),
                "base" => y.osm_base = f.get(1).unwrap_or(&"").to_string(),
                "promoted" => {
                    let was = f.get(2).and_then(|v| Kind::from_name(v)).ok_or_else(|| bad("bad kind"))?;
                    y.promoted.push((id(1)?, was));
                }
                "node" => y.nodes.push(Node { osm: id(1)?, x: num(2)?, y: num(3)? }),
                "edge" => {
                    let kind = f.get(3).and_then(|v| Kind::from_name(v)).ok_or_else(|| bad("bad kind"))?;
                    let mut poly = Vec::new();
                    for pair in f.get(6).ok_or_else(|| bad("no shape"))?.split(';') {
                        let (px, py) = pair.split_once(',').ok_or_else(|| bad("bad shape"))?;
                        poly.push((
                            px.parse().map_err(|_| bad("bad shape"))?,
                            py.parse().map_err(|_| bad("bad shape"))?,
                        ));
                    }
                    y.edges.push(Edge { a: idx(1)?, b: idx(2)?, kind, len: num(4)?, way: id(5)?, poly });
                }
                "point" => y.points.push(Point { node: idx(1)?, stem: idx(2)?, normal: idx(3)?, reverse: idx(4)? }),
                "crossing" => {
                    if f.len() < 6 || f.len() % 2 != 0 {
                        return Err(bad("a crossing needs a node and at least two pairs of edges"));
                    }
                    let pairs = (2..f.len()).step_by(2).map(|i| Ok((idx(i)?, idx(i + 1)?))).collect::<Result<_, YardError>>()?;
                    y.crossings.push(Crossing { node: idx(1)?, pairs });
                }
                "platform" => y.platforms.push(Platform {
                    name: f.get(1).ok_or_else(|| bad("no name"))?.to_string(),
                    edge: idx(2)?,
                    len: num(3)?,
                    way: id(4)?,
                }),
                "portal" => y.portals.push(Portal {
                    name: f.get(1).ok_or_else(|| bad("no name"))?.to_string(),
                    node: idx(2)?,
                    edge: idx(3)?,
                }),
                "signal" => y.signals.push(Signal {
                    name: f.get(1).ok_or_else(|| bad("no name"))?.to_string(),
                    kind: f.get(2).and_then(|v| SignalKind::from_name(v)).ok_or_else(|| bad("bad signal kind"))?,
                    edge: idx(3)?,
                    offset: num(4)?,
                    forward: match f.get(5) {
                        Some(&"ab") => true,
                        Some(&"ba") => false,
                        _ => return Err(bad("direction must be ab or ba")),
                    },
                    origin: f.get(6).and_then(|v| Origin::from_name(v)).ok_or_else(|| bad("bad origin"))?,
                    platform: match f.get(7) {
                        Some(&"-") => None,
                        _ => Some(idx(7)?),
                    },
                }),
                other => return Err(bad(&format!("unknown record '{other}'"))),
            }
        }
        if !seen_header {
            return Err(YardError("missing 'yard 3' header".into()));
        }
        y.check_refs()?;
        Ok(y)
    }

    /// Every index a record holds must point at a record that exists, so the
    /// game never indexes out of range on a hand-edited or truncated file.
    fn check_refs(&self) -> Result<(), YardError> {
        let (n, e) = (self.nodes.len(), self.edges.len());
        let bad = |what: &str| Err(YardError(format!("dangling index in {what}")));
        for ed in &self.edges {
            if ed.a >= n || ed.b >= n {
                return bad("edge");
            }
        }
        for p in &self.points {
            if p.node >= n || p.stem >= e || p.normal >= e || p.reverse >= e {
                return bad("point");
            }
        }
        for c in &self.crossings {
            if c.node >= n || c.pairs.iter().any(|q| q.0 >= e || q.1 >= e) {
                return bad("crossing");
            }
        }
        for p in &self.platforms {
            if p.edge >= e {
                return bad("platform");
            }
        }
        for p in &self.portals {
            if p.node >= n || p.edge >= e {
                return bad("portal");
            }
        }
        for s in &self.signals {
            if s.edge >= e || s.platform.is_some_and(|p| p >= self.platforms.len()) {
                return bad("signal");
            }
        }
        Ok(())
    }

    pub fn graph(&self) -> Graph {
        let mut inc = vec![Vec::new(); self.nodes.len()];
        for (k, e) in self.edges.iter().enumerate() {
            inc[e.a].push(k);
            if e.b != e.a {
                inc[e.b].push(k);
            }
        }
        let mut at: Vec<Junction> = inc
            .iter()
            .map(|v| match v.len() {
                0 | 1 => Junction::End,
                2 => Junction::Through,
                _ => Junction::Other,
            })
            .collect();
        for (k, p) in self.points.iter().enumerate() {
            at[p.node] = Junction::Point(k);
        }
        for (k, c) in self.crossings.iter().enumerate() {
            at[c.node] = Junction::Crossing(k);
        }
        // A portal is where the extract is cut: two running ways can meet
        // there (N4), and degree alone would read that as a through node and
        // let a train turn back over it. Last, so it wins over any record.
        for p in &self.portals {
            at[p.node] = Junction::End;
        }
        Graph { inc, at }
    }

    /// The node a train running over `edge` in direction `forward` heads for.
    pub fn head(&self, edge: usize, forward: bool) -> usize {
        let e = &self.edges[edge];
        if forward { e.b } else { e.a }
    }
}

/// What a node is to a train passing over it.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Junction {
    /// A buffer stop, an unmapped end, or a portal: nowhere further to go.
    End,
    /// Two edges meeting with no choice: a way boundary or a bend.
    Through,
    Point(usize),
    Crossing(usize),
    /// Three or more edges with no point or crossing record. The B0 extract
    /// has none; a train may take any edge out, as `cabin-osm` assumes.
    Other,
}

pub struct Graph {
    /// Edges meeting at each node.
    pub inc: Vec<Vec<usize>>,
    pub at: Vec<Junction>,
}

impl Graph {
    /// Where a train running over `edge` in direction `forward` may go next,
    /// as (edge, forward) pairs: on a point's stem it chooses a leg, on a leg
    /// it takes the stem, over a crossing it takes any pair it is in: straight
    /// on at a diamond, straight or diverging at a slip, straight first.
    pub fn next(&self, yard: &Yard, edge: usize, forward: bool) -> Vec<(usize, bool)> {
        let n = yard.head(edge, forward);
        let out: Vec<usize> = match self.at[n] {
            Junction::End => vec![],
            Junction::Through | Junction::Other => self.inc[n].iter().copied().filter(|&x| x != edge).collect(),
            Junction::Point(k) => {
                let p = &yard.points[k];
                if edge == p.stem {
                    vec![p.normal, p.reverse]
                } else if edge == p.normal || edge == p.reverse {
                    vec![p.stem]
                } else {
                    vec![]
                }
            }
            Junction::Crossing(k) => yard.crossings[k]
                .pairs
                .iter()
                .filter_map(|&(p, q)| if p == edge { Some(q) } else if q == edge { Some(p) } else { None })
                .collect(),
        };
        // A loop edge (both ends at n) has no single way in; skip it.
        out.into_iter()
            .filter(|&x| yard.edges[x].a != yard.edges[x].b)
            .map(|x| (x, yard.edges[x].a == n))
            .collect()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn tiny() -> Yard {
        Yard {
            origin: (28.642, 77.219),
            osm_base: "2026-11-15T07:17:26Z".into(),
            promoted: vec![(11, Kind::Yard)],
            nodes: vec![
                Node { osm: 1, x: 0.0, y: 0.0 },
                Node { osm: 2, x: 100.0, y: 0.0 },
                Node { osm: 3, x: 200.0, y: 5.5 },
            ],
            edges: vec![
                Edge { a: 0, b: 1, kind: Kind::Running, len: 100.0, way: 10, poly: vec![(0.0, 0.0), (100.0, 0.0)] },
                Edge { a: 1, b: 2, kind: Kind::Running, len: 100.1, way: 11, poly: vec![(100.0, 0.0), (200.0, 5.5)] },
            ],
            points: vec![Point { node: 1, stem: 0, normal: 1, reverse: 1 }],
            // Indices only: the round trip must keep a slip's extra pairs.
            crossings: vec![Crossing { node: 2, pairs: vec![(0, 1), (1, 0), (0, 0)] }],
            platforms: vec![Platform { name: "P1".into(), way: 99, edge: 1, len: 80.0 }],
            portals: vec![Portal { name: "W1".into(), node: 0, edge: 0 }],
            signals: vec![Signal {
                name: "HW1".into(),
                kind: SignalKind::Home,
                edge: 0,
                offset: 70.0,
                forward: true,
                origin: Origin::Generated,
                platform: None,
            }],
        }
    }

    #[test]
    fn round_trip_is_exact() {
        let y = tiny();
        let text = y.to_text();
        assert_eq!(Yard::parse(&text), Ok(y));
    }

    #[test]
    fn dangling_index_is_refused() {
        let text = tiny().to_text().replace("portal W1 0 0", "portal W1 0 9");
        assert!(Yard::parse(&text).is_err());
    }
}
